content.text:
Brief:
A paper kite rides the wind over the rooftops. Tap to rise, avoid the chimneys and collect ribbons while the wind slowly speeds up.

Plan:
{"gameType":"arcade-run","input":"tap-anywhere","lang":"en","loop":"Tap to make the paper kite rise on the wind, dodging chimneys and collecting ribbons as the breeze speeds up. Hitting a chimney ends the flight and shows your ribbon score.","slug":"kite-over-the-rooftops","style":"paper-cut","title":"Kite Over the Rooftops"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Kite Over the Rooftops</title>
7| <style>
8|   html, body {
9|     margin: 0;
10|     padding: 0;
11|     width: 100%;
12|     height: 100%;
13|     background: #f4ecd8;
14|     overflow: hidden;
15|     font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
16|   }
17|   canvas {
18|     display: block;
19|     width: 100vw;
20|     height: 100dvh;
21|     touch-action: none;
22|   }
23| </style>
24| </head>
25| <body>
26| <canvas id="game"></canvas>
27| <script>
28|   const CARTRIDGE = {
29|     send(type, payload = {}) {
30|       window.parent.postMessage(
31|         { source: "cartridge", v: 1, type, payload },
32|         "*",
33|       );
34|     },
35|   };
36| </script>
37| <script>
38| (function () {
39|   const canvas = document.getElementById("game");
40|   const ctx = canvas.getContext("2d");
41| 
42|   let dpr = Math.max(1, window.devicePixelRatio || 1);
43|   let W = 0, H = 0;
44| 
45|   function resize() {
46|     W = window.innerWidth;
47|     H = window.innerHeight;
48|     dpr = Math.max(1, window.devicePixelRatio || 1);
49|     canvas.width = Math.floor(W * dpr);
50|     canvas.height = Math.floor(H * dpr);
51|     canvas.style.width = W + "px";
52|     canvas.style.height = H + "px";
53|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
54|   }
55|   window.addEventListener("resize", resize);
56|   resize();
57| 
58|   // ---------- palette ----------
59|   const COL_BG = "#f4ecd8";
60|   const COL_LAYER = "#e07a5f";
61|   const COL_ACCENT = "#3d405b";
62|   const COL_HILITE = "#81b29a";
63| 
64|   // ---------- seeded jitter helpers ----------
65|   function seededRand(seed) {
66|     let s = seed % 2147483647;
67|     if (s <= 0) s += 2147483646;
68|     return function () {
69|       s = (s * 16807) % 2147483647;
70|       return (s - 1) / 2147483646;
71|     };
72|   }
73|   const jitterRand = seededRand(12345);
74|   function jitter(v, amt) {
75|     return v + (jitterRand() - 0.5) * amt * 2;
76|   }
77| 
78|   function roundedRectPath(x, y, w, h, r) {
79|     ctx.beginPath();
80|     ctx.moveTo(x + r, y);
81|     ctx.lineTo(x + w - r, y);
82|     ctx.arcTo(x + w, y, x + w, y + r, r);
83|     ctx.lineTo(x + w, y + h - r);
84|     ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
85|     ctx.lineTo(x + r, y + h);
86|     ctx.arcTo(x, y + h, x, y + h - r, r);
87|     ctx.lineTo(x, y + r);
88|     ctx.arcTo(x, y, x + r, y, r);
89|     ctx.closePath();
90|   }
91| 
92|   function jitterPolygon(points, seedOffset) {
93|     const rnd = seededRand(9000 + seedOffset);
94|     return points.map(([px, py]) => [
95|       px + (rnd() - 0.5) * 3,
96|       py + (rnd() - 0.5) * 3,
97|     ]);
98|   }
99| 
100|   function drawPaperShape(pathFn, fillColor, shadow) {
101|     ctx.save();
102|     if (shadow) {
103|       ctx.shadowColor = "rgba(61,64,91,0.35)";
104|       ctx.shadowBlur = 6;
105|       ctx.shadowOffsetY = 3;
106|     }
107|     ctx.fillStyle = fillColor;
108|     pathFn();
109|     ctx.fill();
110|     ctx.restore();
111|   }
112| 
113|   // ---------- game state ----------
114|   let last = 0;
115|   let running = false;
116|   let paused = false;
117|   let started = false; // whether boot happened
118|   let score = 0;
119|   let scoreSent = -1;
120|   let gameOverShown = false;
121| 
122|   let kiteY = 0;
123|   let kiteVY = 0;
124|   const kiteX = 0; // set relative to W
125|   let windSpeed = 160; // px/s scroll speed, ramps up
126|   let elapsed = 0;
127| 
128|   let chimneys = [];
129|   let ribbons = [];
130|   let clouds = [];
131|   let spawnTimer = 0;
132|   let ribbonTimer = 0;
133| 
134|   const GRAVITY = 480;
135|   const FLAP = -260;
136|   const KITE_R = 22;
137| 
138|   function initClouds() {
139|     clouds = [];
140|     for (let i = 0; i < 5; i++) {
141|       clouds.push({
142|         x: Math.random() * 800,
143|         y: 40 + Math.random() * 150,
144|         s: 0.6 + Math.random() * 0.8,
145|         speed: 20 + Math.random() * 20,
146|       });
147|     }
148|   }
149| 
150|   function resetGameState() {
151|     score = 0;
152|     scoreSent = -1;
153|     elapsed = 0;
154|     windSpeed = 160;
155|     kiteY = H / 2;
156|     kiteVY = 0;
157|     chimneys = [];
158|     ribbons = [];
159|     spawnTimer = 2.2; // fairness: keep opening lane clear a bit
160|     ribbonTimer = 1.2;
161|     gameOverShown = false;
162|     initClouds();
163|   }
164| 
165|   function backToTitle() {
166|     running = false;
167|     paused = false;
168|     resetGameState();
169|   }
170| 
171|   resetGameState();
172| 
173|   // ---------- spawning ----------
174|   function spawnChimney() {
175|     const gapH = Math.max(120, 230 - elapsed * 3);
176|     const margin = 60;
177|     const centerY = margin + Math.random() * (H - margin * 2 - gapH) + gapH / 2;
178|     chimneys.push({
179|       x: W + 60,
180|       w: 46,
181|       gapCenter: centerY,
182|       gapH: gapH,
183|       passed: false,
184|       seed: Math.floor(Math.random() * 10000),
185|     });
186|   }
187| 
188|   function spawnRibbon() {
189|     ribbons.push({
190|       x: W + 40,
191|       y: 60 + Math.random() * (H - 120),
192|       r: 12,
193|       taken: false,
194|       seed: Math.floor(Math.random() * 10000),
195|       bob: Math.random() * Math.PI * 2,
196|     });
197|   }
198| 
199|   // ---------- update ----------
200|   function advance(dt) {
201|     elapsed += dt;
202|     windSpeed = 160 + Math.min(elapsed * 4, 160); // ramps up to 320
203| 
204|     // clouds always drift for idle liveliness
205|     for (const c of clouds) {
206|       c.x -= c.speed * dt;
207|       if (c.x < -100) c.x = W + 100;
208|     }
209| 
210|     if (!running) return;
211| 
212|     kiteVY += GRAVITY * dt;
213|     kiteY += kiteVY * dt;
214| 
215|     if (kiteY < KITE_R) {
216|       kiteY = KITE_R;
217|       kiteVY = 0;
218|     }
219|     if (kiteY > H - KITE_R) {
220|       kiteY = H - KITE_R;
221|       kiteVY = 0;
222|     }
223| 
224|     spawnTimer -= dt;
225|     if (spawnTimer <= 0) {
226|       spawnChimney();
227|       spawnTimer = Math.max(1.1, 1.9 - elapsed * 0.01);
228|     }
229|     ribbonTimer -= dt;
230|     if (ribbonTimer <= 0) {
231|       spawnRibbon();
232|       ribbonTimer = 1.6 + Math.random() * 1.2;
233|     }
234| 
235|     for (const c of chimneys) {
236|       c.x -= windSpeed * dt;
237|     }
238|     for (const r of ribbons) {
239|       r.x -= windSpeed * dt;
240|       r.bob += dt * 3;
241|     }
242| 
243|     chimneys = chimneys.filter((c) => c.x > -c.w - 20);
244|     ribbons = ribbons.filter((r) => !r.taken && r.x > -40);
245| 
246|     // scoring: passing chimneys
247|     const kx = W * 0.28;
248|     for (const c of chimneys) {
249|       if (!c.passed && c.x + c.w < kx) {
250|         c.passed = true;
251|         score += 1;
252|       }
253|     }
254|     // ribbons collection
255|     for (const r of ribbons) {
256|       if (r.taken) continue;
257|       const dx = kx - r.x;
258|       const dy = kiteY - r.y;
259|       if (Math.sqrt(dx * dx + dy * dy) < KITE_R + r.r) {
260|         r.taken = true;
261|         score += 3;
262|       }
263|     }
264| 
265|     if (score !== scoreSent) {
266|       scoreSent = score;
267|       CARTRIDGE.send("score", { value: score });
268|     }
269|   }
270| 
271|   function collide() {
272|     if (!running) return;
273|     const kx = W * 0.28;
274|     for (const c of chimneys) {
275|       if (kx + KITE_R > c.x && kx - KITE_R < c.x + c.w) {
276|         const gapTop = c.gapCenter - c.gapH / 2;
277|         const gapBottom = c.gapCenter + c.gapH / 2;
278|         if (kiteY - KITE_R < gapTop || kiteY + KITE_R > gapBottom) {
279|           crash();
280|           return;
281|         }
282|       }
283|     }
284|   }
285| 
286|   function crash() {
287|     running = false;
288|     gameOverShown = true;
289|     CARTRIDGE.send("end", { reason: "lose", value: score });
290|   }
291| 
292|   // ---------- drawing ----------
293|   function drawBackground() {
294|     ctx.fillStyle = COL_BG;
295|     ctx.fillRect(0, 0, W, H);
296| 
297|     // clouds - simple paper-cut puffs
298|     for (const c of clouds) {
299|       drawPaperShape(() => {
300|         ctx.beginPath();
301|         ctx.ellipse(c.x, c.y, 30 * c.s, 16 * c.s, 0, 0, Math.PI * 2);
302|         ctx.ellipse(c.x + 20 * c.s, c.y + 4 * c.s, 20 * c.s, 12 * c.s, 0, 0, Math.PI * 2);
303|         ctx.ellipse(c.x - 20 * c.s, c.y + 4 * c.s, 18 * c.s, 11 * c.s, 0, 0, Math.PI * 2);
304|       }, "#ffffff", false);
305|     }
306| 
307|     // rooftop skyline strip at bottom for depth
308|     drawPaperShape(() => {
309|       ctx.rect(0, H - 30, W, 30);
310|     }, COL_ACCENT, false);
311|   }
312| 
313|   function drawChimney(c) {
314|     const gapTop = c.gapCenter - c.gapH / 2;
315|     const gapBottom = c.gapCenter + c.gapH / 2;
316| 
317|     // top stack
318|     drawPaperShape(() => {
319|       const pts = jitterPolygon(
320|         [
321|           [c.x, -10],
322|           [c.x + c.w, -10],
323|           [c.x + c.w, gapTop],
324|           [c.x, gapTop],
325|         ],
326|         c.seed
327|       );
328|       ctx.beginPath();
329|       ctx.moveTo(pts[0][0], pts[0][1]);
330|       for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
331|       ctx.closePath();
332|     }, COL_LAYER, true);
333| 
334|     // bottom stack
335|     drawPaperShape(() => {
336|       const pts = jitterPolygon(
337|         [
338|           [c.x, gapBottom],
339|           [c.x + c.w, gapBottom],
340|           [c.x + c.w, H + 10],
341|           [c.x, H + 10],
342|         ],
343|         c.seed + 1
344|       );
345|       ctx.beginPath();
346|       ctx.moveTo(pts[0][0], pts[0][1]);
347|       for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
348|       ctx.closePath();
349|     }, COL_LAYER, true);
350| 
351|     // little chimney cap lines (accent bands)
352|     ctx.save();
353|     ctx.fillStyle = COL_ACCENT;
354|     ctx.fillRect(c.x - 2, gapTop - 8, c.w + 4, 8);
355|     ctx.fillRect(c.x - 2, gapBottom, c.w + 4, 8);
356|     ctx.restore();
357|   }
358| 
359|   function drawRibbon(r) {
360|     const bobY = r.y + Math.sin(r.bob) * 4;
361|     drawPaperShape(() => {
362|       const pts = jitterPolygon(
363|         [
364|           [r.x - 10, bobY - 4],
365|           [r.x + 10, bobY - 4],
366|           [r.x + 6, bobY + 10],
367|           [r.x, bobY + 4],
368|           [r.x - 6, bobY + 10],
369|         ],
370|         r.seed
371|       );
372|       ctx.beginPath();
373|       ctx.moveTo(pts[0][0], pts[0][1]);
374|       for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
375|       ctx.closePath();
376|     }, COL_HILITE, true);
377|   }
378| 
379|   const kiteJitterSeed = 555;
380|   function drawKite(x, y) {
381|     ctx.save();
382|     ctx.translate(x, y);
383|     const tilt = Math.max(-0.4, Math.min(0.4, kiteVY / 900));
384|     ctx.rotate(tilt);
385| 
386|     // tail
387|     ctx.save();
388|     ctx.strokeStyle = COL_ACCENT;
389|     ctx.lineWidth = 2;
390|     ctx.beginPath();
391|     ctx.moveTo(-KITE_R * 0.6, KITE_R * 0.7);
392|     ctx.quadraticCurveTo(-KITE_R * 1.6, KITE_R * 1.4, -KITE_R * 2.4, KITE_R * 0.9);
393|     ctx.stroke();
394|     ctx.restore();
395| 
396|     // kite body - diamond paper cut
397|     drawPaperShape(() => {
398|       const pts = jitterPolygon(
399|         [
400|           [0, -KITE_R],
401|           [KITE_R * 0.85, 0],
402|           [0, KITE_R],
403|           [-KITE_R * 0.85, 0],
404|         ],
405|         kiteJitterSeed
406|       );
407|       ctx.beginPath();
408|       ctx.moveTo(pts[0][0], pts[0][1]);
409|       for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
410|       ctx.closePath();
411|     }, COL_LAYER, true);
412| 
413|     // inner accent cross
414|     ctx.save();
415|     ctx.strokeStyle = COL_ACCENT;
416|     ctx.lineWidth = 1.5;
417|     ctx.beginPath();
418|     ctx.moveTo(0, -KITE_R);
419|     ctx.lineTo(0, KITE_R);
420|     ctx.moveTo(-KITE_R * 0.85, 0);
421|     ctx.lineTo(KITE_R * 0.85, 0);
422|     ctx.stroke();
423|     ctx.restore();
424| 
425|     ctx.restore();
426|   }
427| 
428|   function drawCardPlate(text, subtext, x, y, w, h) {
429|     drawPaperShape(() => {
430|       roundedRectPath(jitter(x, 1), jitter(y, 1), w, h, 14);
431|     }, "#fffaf0", true);
432|     ctx.save();
433|     ctx.fillStyle = COL_ACCENT;
434|     ctx.textAlign = "center";
435|     ctx.font = "bold 26px -apple-system, Segoe UI, Roboto, Arial, sans-serif";
436|     ctx.fillText(text, x + w / 2, y + h / 2 - (subtext ? 8 : -6));
437|     if (subtext) {
438|       ctx.font = "16px -apple-system, Segoe UI, Roboto, Arial, sans-serif";
439|       ctx.fillText(subtext, x + w / 2, y + h / 2 + 20);
440|     }
441|     ctx.restore();
442|   }
443| 
444|   let hintPulse = 0;
445|   function draw() {
446|     drawBackground();
447| 
448|     for (const c of chimneys) drawChimney(c);
449|     for (const r of ribbons) if (!r.taken) drawRibbon(r);
450| 
451|     const kx = W * 0.28;
452|     drawKite(kx, kiteY);
453| 
454|     // score plate top-left
455|     const plateW = 120, plateH = 46;
456|     drawPaperShape(() => {
457|       roundedRectPath(14, 14, plateW, plateH, 10);
458|     }, "#fffaf0", true);
459|     ctx.save();
460|     ctx.fillStyle = COL_ACCENT;
461|     ctx.font = "bold 20px -apple-system, Segoe UI, Roboto, Arial, sans-serif";
462|     ctx.textAlign = "left";
463|     ctx.fillText("Ribbons: " + score, 26, 14 + plateH / 2 + 7);
464|     ctx.restore();
465| 
466|     if (!running) {
467|       hintPulse += 0.05;
468|       const alpha = 0.6 + Math.sin(hintPulse) * 0.4;
469|       const w = Math.min(320, W * 0.8);
470|       const h = 110;
471|       const x = W / 2 - w / 2;
472|       const y = H / 2 - h / 2;
473|       if (gameOverShown) {
474|         drawCardPlate("Flight Over", "Ribbons collected: " + score + " — tap to fly again", x, y, w, h);
475|       } else {
476|         ctx.save();
477|         ctx.globalAlpha = alpha;
478|         drawCardPlate("Tap to begin", "Ride the wind, dodge the chimneys", x, y, w, h);
479|         ctx.restore();
480|       }
481|     }
482|   }
483| 
484|   // ---------- input ----------
485|   canvas.style.touchAction = "none";
486|   canvas.addEventListener("pointerdown", (event) => {
487|     event.preventDefault();
488|     if (paused) return;
489|     if (!running) {
490|       if (gameOverShown) {
491|         resetGameState();
492|       }
493|       running = true;
494|       CARTRIDGE.send("start");
495|       return;
496|     }
497|     act();
498|   });
499| 
500|   function act() {
501|     kiteVY = FLAP;
502|   }
503| 
504|   // ---------- host messages ----------
505|   window.addEventListener("message", (event) => {
506|     const data = event.data;
507|     if (!data || data.source !== "cartridge-host") return;
508|     if (data.type === "pause") paused = true;
509|     if (data.type === "resume") paused = false;
510|     if (data.type === "reset") backToTitle();
511|   });
512| 
513|   // ---------- main loop ----------
514|   function frame(now) {
515|     const dt = Math.min((now - last) / 1000, 0.05);
516|     last = now;
517|     if (running && !paused) {
518|       advance(dt);
519|       collide();
520|     } else if (!paused) {
521|       // idle animation for clouds even before start
522|       advance(Math.min(dt, 0.05));
523|     }
524|     draw();
525|     if (!started) {
526|       started = true;
527|       CARTRIDGE.send("boot", { title: "Kite Over the Rooftops", gameType: "arcade-run", lang: "en" });
528|     }
529|     requestAnimationFrame(frame);
530|   }
531| 
532|   requestAnimationFrame((t) => {
533|     last = t;
534|     requestAnimationFrame(frame);
535|   });
536| })();
537| </script>
538| </body>
539| </html>
540|

